function pdfText(value){return [...String(value)].map(char=>{const n=char.codePointAt(0);return n<=255||'€‚ƒ„…†‡ˆ‰Š‹ŒŽ‘’“”•–—˜™š›œžŸ'.includes(char)?char:'?';}).join('');}
function wrapText(value,maxWidth,font,size){const lines=[''];for(const word of String(value).split(/\s+/)){let part=word;while(part){const index=lines.length-1,space=lines[index]?' ':'';if(font.widthOfTextAtSize(pdfText(lines[index]+space+part),size)<=maxWidth){lines[index]+=space+part;break;}if(lines[index]){lines.push('');continue;}let end=1;while(end<part.length&&font.widthOfTextAtSize(pdfText(part.slice(0,end+1)),size)<=maxWidth)end++;lines[index]=part.slice(0,end);part=part.slice(end);if(part)lines.push('');}}return lines;}
function renderDocumentation(){const stateLabel={confirmed:'Confirmado',estimated:'Estimado',missing:'Em falta'};$('#documentation-content').innerHTML=`<div class="document-callout"><strong>73,396 m² exteriores. 72 m² comerciais.</strong><p>A área útil certificada não consta dos anexos. O cálculo interior da maquete usa paredes de 100 mm e divisórias de 80 mm assumidas. O alpendre é separado.</p></div><h3>Mapa dimensional</h3><div class="table-scroll"><table class="source-table"><thead><tr><th>Medida</th><th>Valor</th><th>Estado</th><th>Origem / limite</th></tr></thead><tbody>${MEASURES.map(d=>`<tr><td>${esc(d.label)}</td><td>${d.value===null?'Não documentado':d.value.toFixed(3).replace('.',',')+' m'}</td><td><span class="status-label ${d.status}">${stateLabel[d.status]}</span></td><td>${esc(d.source)}${d.note?'<small>'+esc(d.note)+'</small>':''}</td></tr>`).join('')}</tbody></table></div><h3>Divergências preservadas</h3><ul class="source-list">${SOURCE_DIVERGENCES.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><h3>Inventário das referências</h3><div class="source-cards">${SOURCES.map(s=>`<article><h4>${esc(s.label)}</h4><p>${esc(s.scope)}</p><small>${esc(s.locations)}</small><p>${esc(s.limits)}</p><a href="${s.file}" target="_blank" rel="noopener">Abrir fonte ↗</a></article>`).join('')}</div><h3>Vídeos originais recebidos</h3><p class="source-note">Quatro visitas a unidades abertas, com diferenças de dimensão nominal, vãos e acabamentos. Os detalhes visíveis apoiam a apresentação; as cotas confirmadas continuam a ser as das plantas.</p><div class="evidence-links"><button class="outline" data-go="films">Explorar os quatro vídeos ↗</button><a class="outline" href="assets/reference-videos/source-inventory.json" download>Inventário dos vídeos ↓</a></div><h3>Materiais e evidências</h3><div class="evidence-links"><a class="outline" href="assets/evidence-r5/audit-report.html" target="_blank" rel="noopener">Ambientes, cor e auditoria R5 ↗</a><a class="outline" href="assets/interior-r5/source-inventory.json" download>32 referências de cozinha e banho ↓</a><a class="outline" href="assets/catalogue-r3/material-r3-ledger.json" download>Mapa dos 71 materiais ↓</a><a class="outline" href="assets/catalogue-r3/floor-visual-metrics.json" download>Cor e repetição dos pisos ↓</a><a class="outline" href="assets/evidence-r4/audit-report.html" target="_blank" rel="noopener">Expansão corrigida e auditoria R4 ↗</a><a class="outline" href="assets/evidence-r3/audit-report.html" target="_blank" rel="noopener">Materiais e histórico R3 ↗</a><a class="outline" href="assets/evidence-r3/dimensions.json" download>Medidas e fontes JSON ↓</a></div><p class="source-note">A tolerância de cálculo usada é 0,0000001 m; destina-se apenas a comparações numéricas. Não é uma tolerância de fabrico. Não foram fornecidos mapas PBR medidos, RAL/NCS, projectos de instalações ou sequência original de expansão desta variante. Os quatro vídeos recebidos mostram unidades já abertas.</p>`;}
